// ════════════════════════════════════════════════════════════════════
// Code – Normalize & Validate Lead  |  Flow #2 Lead Capture v3.0
// يستلم من 5 مصادر: WhatsApp, Telegram Bot, Instagram Meta,
//   Website Form, Flow #1 Radar
// يُنتج كائناً موحداً متوافقاً مع جميع أعمدة شيت leads
// ════════════════════════════════════════════════════════════════════

const allItems = $input.all();

// ── 1. البحث عن أول عنصر يحتوي بيانات حقيقية ──────────────────
let d = null;
for (const item of allItems) {
  const j = item.json || {};
  if (j.name || j.phone || j.source || j.event_type || j.From ||
      j.content_hash || j.radar_source || j.form_type) {
    d = (j.body && typeof j.body === 'object' && !Array.isArray(j.body))
        ? { ...j.body, _headers: j.headers } : j;
    break;
  }
}
if (!d) d = allItems[0]?.json || {};

// ── 2. اكتشاف المصدر ──────────────────────────────────────────
let source = 'Unknown';
if      (d.event_type === 'message:received:new') source = 'WhatsApp_TimelinesAI';
else if (d.From && d.Body)                        source = 'WhatsApp';
else if (d.message?.from && d.message?.text)      source = 'Telegram_Bot';
else if (d.entry?.[0]?.messaging)                 source = 'Instagram_Meta';
else if (d.radar_source || d.content_hash)        source = 'Radar_' + (d.platform || 'Social');
else if (d.source === 'Website_Form' || d.form_type) source = 'Website_Form';
// الربط مع Flow #1: يأتي عبر webhook lead-from-radar
else if (d.radar_intent || d.radar_quality)       source = 'Radar_' + (d.platform || 'Social');

// ── 3. استخراج وتوحيد رقم الهاتف ────────────────────────────
let phone = '';
if      (source === 'WhatsApp_TimelinesAI') phone = d.chat?.phone || d.message?.sender?.phone || '';
else if (source === 'WhatsApp')             phone = (d.From || '').replace('whatsapp:','');
else if (source === 'Telegram_Bot')         phone = d.message?.contact?.phone_number || d.contact?.phone || '';
else if (source.startsWith('Radar_'))       phone = (d.phones_found?.[0]) || d.phone || '';
else                                        phone = d.phone || d.mobile || d.tel || d.whatsapp || '';

phone = phone.toString().replace(/[\s\-().]/g,'');
if      (phone.startsWith('00966'))              phone = '+966' + phone.slice(5);
else if (phone.startsWith('966') && phone.length>=12) phone = '+966' + phone.slice(3);
else if (phone.startsWith('05') && phone.length===10) phone = '+966' + phone.slice(1);
else if (phone.startsWith('5')  && phone.length===9)  phone = '+9665' + phone.slice(1);
else if (phone.length > 5 && !phone.startsWith('+'))  phone = '+' + phone.replace(/^0+/,'');

const phoneValid = /^\+[0-9]{7,15}$/.test(phone);

// ── 4. استخراج الاسم ─────────────────────────────────────────
let name = '';
if      (source === 'WhatsApp_TimelinesAI') name = d.chat?.full_name || d.message?.sender?.full_name || '';
else if (source === 'WhatsApp')             name = d.ProfileName || d.name || '';
else if (source === 'Telegram_Bot')         name = [d.message?.from?.first_name, d.message?.from?.last_name].filter(Boolean).join(' ');
else if (source.startsWith('Radar_'))       name = d.full_name || d.username || '';
else                                        name = d.name || d.full_name || '';
name = name.trim() || 'غير معروف';

// ── 5. استخراج الرسالة ────────────────────────────────────────
let message = '';
if      (source === 'WhatsApp_TimelinesAI') message = d.message?.text || '';
else if (source === 'WhatsApp')             message = d.Body || '';
else if (source === 'Telegram_Bot')         message = d.message?.text || '';
else if (source === 'Instagram_Meta')       message = d.entry?.[0]?.messaging?.[0]?.message?.text || '';
else if (source.startsWith('Radar_'))       message = d.raw_text || d.text || '';
else                                        message = d.message || d.inquiry || d.notes || '';

// ── 6. بريد إلكتروني + pax ───────────────────────────────────
const email = (d.email || '').trim().toLowerCase();
const paxMatch = message.match(/(\d+)\s*(شخص|أشخاص|نفر|غرف|غرفة|pax)/i);
const pax_hint = paxMatch ? parseInt(paxMatch[1]) : (d.pax_hint || 0);

// ── 7. الجنسية من النص ───────────────────────────────────────
function detectNationality(txt) {
  const t = (txt||'').toLowerCase();
  if (/سعودي|الرياض|جدة|الدمام|مكة|المدينة/.test(t))    return 'سعودي';
  if (/إماراتي|دبي|أبوظبي|الشارقة/.test(t))          return 'إماراتي';
  if (/كويتي|الكويت/.test(t))                return 'كويتي';
  if (/قطري|الدوحة/.test(t))                 return 'قطري';
  if (/بحريني|المنامة/.test(t))              return 'بحريني';
  if (/عماني|مسقط/.test(t))                 return 'عماني';
  if (/مغربي|المغرب|كازا|الرباط|مراكش/.test(t))       return 'مغربي';
  if (/مصري|القاهرة/.test(t))                return 'مصري';
  if (/أردني|عمان|الأردن/.test(t))           return 'أردني';
  return d.nationality || '';
}
const nationality = detectNationality(message);

// ── 8. بيانات Radar (من Flow #1) ─────────────────────────────
const radar_intent    = d.radar_intent    || d.intent    || '';
const radar_urgency   = d.radar_urgency   || d.urgency   || '';
const radar_quality   = Number(d.radar_quality || d.lead_quality || 0);
const budget_signal   = d.budget_signal   || 'unknown';
const travel_group    = d.travel_group    || 'unknown';
const stars_preference= d.stars_preference|| 'unknown';
const check_in_hint   = d.check_in_hint   || '';
const nights_hint     = Number(d.nights_hint || 0);
const content_hash    = d.content_hash    || '';
const platform        = d.platform        || source.replace('Radar_','') || '';

// ── 9. توليد lead_id ─────────────────────────────────────────
function genLeadId() {
  const ts  = Date.now().toString().slice(-6);
  const rnd = Math.floor(Math.random()*1000).toString().padStart(3,'0');
  return `LD-${ts}${rnd}`;
}

// ── 10. تحديد category ───────────────────────────────────────
function getCategory(intent, quality) {
  if (intent === 'booking_ready' || /حجز|فندق|سائق/.test(message)) return 'HOT';
  if (['booking_research','travel_planning'].includes(intent)) return 'WARM';
  if (quality >= 50)                                           return 'WARM';
  if (quality > 0)                                             return 'WARM';
  // للمصادر المباشرة (WhatsApp/Form) نعتبرها WARM تلقائياً
  return source === 'Unknown' ? 'COLD' : 'WARM';
}
const category = getCategory(radar_intent, radar_quality);

// ── 11. journey_step ─────────────────────────────────────────
function getJourneyStep(intent, urgency, src) {
  if (intent === 'booking_ready' && urgency === 'immediate') return 'hot_immediate';
  if (intent === 'booking_ready')                            return 'hot';
  if (intent === 'booking_research')                         return 'warm_research';
  if (intent === 'travel_planning')                          return 'warm_planning';
  if (src.startsWith('Radar_'))                              return 'warm_radar';
  if (src === 'WhatsApp' || src === 'WhatsApp_TimelinesAI')  return 'warm_whatsapp';
  if (src === 'Website_Form')                                return 'warm_form';
  if (src === 'Telegram_Bot')                                return 'warm_telegram';
  if (src === 'Instagram_Meta')                              return 'warm_instagram';
  return 'cold_info';
}
const journey_step = getJourneyStep(radar_intent, radar_urgency, source);

// ── 12. المخرج النهائي الكامل ────────────────────────────────
return [{ json: {
  // ── هوية ───────────────────────────────
  lead_id:          genLeadId(),
  phone:            phone,
  phone_valid:      phoneValid,
  name:             name,
  email:            email,
  nationality:      nationality,

  // ── مصدر ───────────────────────────────
  source:           source,
  platform:         platform,
  content_hash:     content_hash,

  // ── رسالة ──────────────────────────────
  message:          message.substring(0, 500),
  last_message:     message.substring(0, 500),
  pax_hint:         pax_hint,

  // ── رادار ──────────────────────────────
  radar_intent:     radar_intent,
  radar_urgency:    radar_urgency,
  radar_quality:    radar_quality,
  score:            radar_quality,
  category:         category,
  budget_signal:    budget_signal,
  travel_group:     travel_group,
  stars_preference: stars_preference,
  check_in_hint:    check_in_hint,
  nights_hint:      nights_hint,

  // ── رحلة ───────────────────────────────
  journey_step:     journey_step,
  consent:          'TRUE',
  status:           'new',

  // ── وقت ────────────────────────────────
  received_at:      new Date().toISOString(),
  created_at:       new Date().toISOString(),
  updated_at:       new Date().toISOString(),
  assigned_to:      '',
  notes:            d.ai_reason || d.notes || '',

  // ── للتشخيص ────────────────────────────
  _source_detected: source,
  _items_checked:   allItems.length,
  _phone_raw:       d.phone || d.From || ''
}}];

// ════════════════════════════════════════════════════════════════════
// Code – Rate Limit per Phone (GSheets-based, no env vars)
// يتحقق من عدد التفاعلات في الساعة الأخيرة
// ════════════════════════════════════════════════════════════════════
const item = $input.first().json;
const RATE_LIMIT_MAX = 5;
const RATE_WINDOW_MS = 3600000; // 1 hour

// نستخدم Static Data لتخزين مؤقت خفيف (يُعاد عند restart Bluevia)
const store = $getWorkflowStaticData('node');
const key = 'rl_' + (item.phone || 'unknown').replace(/[^\d]/g,'');
const now = Date.now();

let timestamps = store[key] || [];
timestamps = timestamps.filter(ts => now - ts < RATE_WINDOW_MS);
const rate_limited = timestamps.length >= RATE_LIMIT_MAX;
if (!rate_limited) {
  timestamps.push(now);
  store[key] = timestamps;
}

return [{ json: {
  ...item,
  rate_limited,
  request_count: timestamps.length,
  rate_reset_at: new Date(now + RATE_WINDOW_MS).toISOString()
}}];

